namespace BobbyBoi;
static class SfxTests {
 public static void Run(){Directory.CreateDirectory("artifacts/sfx");var hashes=new HashSet<string>();foreach(string cue in WorldAudio.Cues){var pcm=WorldAudio.GetSamples(cue);if(pcm.Length<1000||pcm.Length>WorldAudio.Rate*2||pcm.Any(v=>!float.IsFinite(v)||Math.Abs(v)>1)||pcm.Max(Math.Abs)<.05)throw new Exception("Invalid audio cue "+cue);var bytes=WorldAudio.Wave(cue);if(System.Text.Encoding.ASCII.GetString(bytes,0,4)!="RIFF"||BitConverter.ToInt32(bytes,40)!=pcm.Length*2||bytes.Length!=44+pcm.Length*2)throw new Exception("Invalid WAV "+cue);hashes.Add(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes)));if(cue is "death" or "explosion" or "cast" or "bite")File.WriteAllBytes("artifacts/sfx/"+cue+".wav",bytes);}if(hashes.Count<WorldAudio.Cues.Length*.8)throw new Exception("SFX bank lacks distinct sounds");WorldAudio.VerifyMixer();WorldAudio.Play("explosion",0);if(WorldAudio.DeviceOpened)throw new Exception("Mute opened audio device");File.WriteAllText("artifacts/sfx-tests.txt",$"PASS: {WorldAudio.Cues.Length} valid original PCM effects; {hashes.Count} distinct waveforms; overlap, clipping limiter and voice cleanup; mute stays silent.\n");}
 public static void Playback(){Directory.CreateDirectory("artifacts");int volume=SaveData.Load().Volume;if(volume==0){File.WriteAllText("artifacts/sfx-playback.txt","SKIP: user's volume is muted; no audio device opened.");return;}WorldAudio.Play("cast",volume);Thread.Sleep(350);WorldAudio.Play("bite",volume);WorldAudio.Play("reel",volume);Thread.Sleep(600);WorldAudio.Play("explosion",volume);WorldAudio.Play("death",volume);Thread.Sleep(1100);bool opened=WorldAudio.DeviceOpened;WorldAudio.Stop();File.WriteAllText("artifacts/sfx-playback.txt",$"PASS={opened&&WorldAudio.DeviceError==null}; outputOpened={opened}; volume={volume}; error={WorldAudio.DeviceError??"none"}; cues=cast,bite,reel,explosion+death\n");if(!opened||WorldAudio.DeviceError!=null)Environment.ExitCode=1;}
}
